#!/usr/bin/env python3
"""Write the corpus evidence of nomac's loader envelope (docs/adr/0011-feature-envelope.md).

A corpus app whose every `nomac verify` check is identical to Xcode is evidence for every
loader feature it uses: `nomac check --json` lists them, and each feature is credited to the first
such app in corpus/corpus.json order. The result replaces
Sources/NomacEnvelope/Loader/LoaderEnvelope+Corpus.swift.

Usage: envelope_corpus.py --reports DIR [--checkouts DIR] [--nomac PATH] [--derived-data DIR]

--reports holds `<app>.json` verification reports; --checkouts the apps' checkouts at their
corpus commits (default /tmp/nomac-corpus); remote packages are read from the app's
DerivedData `SourcePackages` when there is one.
"""

import argparse
import glob
import json
import subprocess
import sys
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
OUTPUT = REPO / "Sources" / "NomacEnvelope" / "Loader" / "LoaderEnvelope+Corpus.swift"


def identical(report_path):
    report = json.loads(report_path.read_text())
    checks = report.get("checks", [])
    return bool(checks) and all(check["status"] == "identical" for check in checks)


def source_packages(derived_data, container):
    name = Path(container).stem
    found = sorted(glob.glob(str(Path(derived_data) / f"{name}-*" / "SourcePackages")))
    return found[0] if found else None


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--reports", required=True)
    parser.add_argument("--checkouts", default="/tmp/nomac-corpus")
    parser.add_argument("--nomac", default=str(REPO / ".build" / "debug" / "nomac"))
    parser.add_argument("--derived-data", default=str(Path.home() / "Library" / "Developer" / "Xcode" / "DerivedData"))
    arguments = parser.parse_args()
    corpus = json.loads((REPO / "corpus" / "corpus.json").read_text())
    first = {}
    used = []
    for app in corpus["apps"]:
        report = Path(arguments.reports) / f"{app['id']}.json"
        if not report.exists() or not identical(report):
            continue
        container = Path(arguments.checkouts) / app["id"] / app["container"]
        command = [arguments.nomac, "check", "--json", str(container)]
        packages = source_packages(arguments.derived_data, app["container"])
        if packages:
            command += ["--source-packages", packages]
        result = subprocess.run(command, capture_output=True, text=True)
        if not result.stdout:
            sys.exit(f"nomac check failed for {app['id']}: {result.stderr}")
        used.append(app["id"])
        for feature in json.loads(result.stdout)["features"]:
            if feature["domain"] == "loader":
                first.setdefault(feature["id"], app["id"])
    lines = [
        "// Generated by .github/scripts/envelope_corpus.py from the corpus apps identical to Xcode:",
        "// " + ", ".join(used) + ".",
        "extension LoaderEnvelope {",
        "    static let corpus: [(feature: String, app: String)] = [",
    ]
    lines += [f"        ({json.dumps(feature)}, {json.dumps(app)})," for feature, app in sorted(first.items())]
    lines += ["    ]", "}", ""]
    OUTPUT.write_text("\n".join(lines))
    print(f"{len(first)} features from {len(used)} apps: {', '.join(used)}")


if __name__ == "__main__":
    main()
